function closeActionMenu() { if (activeActionMenu) { activeActionMenu.remove(); activeActionMenu = null; } }

function initRadixSelect(el) { if (!el) return; const trigger = el.querySelector('.radix-select-trigger'), content = el.querySelector('.radix-select-content'), items = el.querySelectorAll('.radix-select-item'); const newTrigger = trigger.cloneNode(true); trigger.parentNode.replaceChild(newTrigger, trigger); newTrigger?.addEventListener('click', e => { e.stopPropagation(); document.querySelectorAll('.radix-select-content').forEach(c => { if (c !== content) c.classList.add('hidden'); }); content?.classList.toggle('hidden'); }); items.forEach(item => item.addEventListener('click', e => { e.stopPropagation(); const v = item.dataset.value; const label = item.textContent.replace(/[💳💵📝🏦🔒📧📱]/g, '').trim(); newTrigger.querySelector('span').textContent = label; newTrigger.setAttribute('data-value', v); items.forEach(i => i.setAttribute('data-selected', 'false')); item.setAttribute('data-selected', 'true'); content?.classList.add('hidden'); })); }
document.addEventListener('click', e => { if (!e.target.closest('.radix-select')) document.querySelectorAll('.radix-select-content').forEach(c => c.classList.add('hidden')); });

function openPaymentModal(invoice) { document.getElementById('paymentInvoiceId').textContent = invoice.id; document.getElementById('paymentPatientName').textContent = invoice.patient; document.getElementById('paymentTotalAmount').textContent = `$${invoice.amount.toFixed(2)}`; document.getElementById('paymentOutstanding').textContent = `$${invoice.balance.toFixed(2)}`; document.getElementById('paymentAmount').value = invoice.balance; document.getElementById('paymentDate').value = new Date().toISOString().slice(0, 10); document.getElementById('paymentModal').style.display = 'grid'; document.getElementById('paymentModalBackdrop').classList.add('show'); document.body.style.overflow = 'hidden'; setTimeout(() => initRadixSelect(document.getElementById('paymentMethodSelect')), 50); }
function closePaymentModal() { document.getElementById('paymentModal').style.display = 'none'; document.getElementById('paymentModalBackdrop').classList.remove('show'); document.body.style.overflow = ''; }
function processPayment() { const invoiceId = document.getElementById('paymentInvoiceId').textContent; const paymentAmount = parseFloat(document.getElementById('paymentAmount').value); const trigger = document.querySelector('#paymentMethodSelect .radix-select-trigger'); const paymentMethod = trigger?.getAttribute('data-value') || 'Credit Card'; const invoice = invoicesData.find(i => i.id === invoiceId); if (invoice && paymentAmount > 0 && paymentAmount <= invoice.balance) { invoice.paidAmount += paymentAmount; invoice.balance -= paymentAmount; invoice.paymentDate = new Date().toISOString().slice(0, 10); invoice.paymentMethod = paymentMethod; invoice.status = invoice.balance === 0 ? "Paid" : "Partially Paid"; renderTables(); showToast(`Payment of $${paymentAmount.toFixed(2)} recorded via ${paymentMethod}`); closePaymentModal(); } else { showToast("Invalid payment amount", true); } }

function openReminderModal(invoice) { pendingReminderInvoice = invoice; document.getElementById('reminderPatientName').textContent = invoice.patient; document.getElementById('reminderInvoiceId').textContent = invoice.id; document.getElementById('reminderAmount').textContent = `$${invoice.balance.toFixed(2)}`; document.getElementById('reminderDueDate').textContent = invoice.dueDate; document.getElementById('reminderMessage').value = `Dear ${invoice.patient},\n\nThis is a reminder that your invoice ${invoice.id} for $${invoice.balance.toFixed(2)} is due on ${invoice.dueDate}.\n\nThank you,\nMeditrack Billing`; document.getElementById('reminderModal').style.display = 'grid'; document.getElementById('reminderModalBackdrop').classList.add('show'); document.body.style.overflow = 'hidden'; setTimeout(() => initRadixSelect(document.getElementById('reminderTypeSelect')), 50); }
function closeReminderModal() { document.getElementById('reminderModal').style.display = 'none'; document.getElementById('reminderModalBackdrop').classList.remove('show'); pendingReminderInvoice = null; document.body.style.overflow = ''; }
function sendReminder() { if (pendingReminderInvoice) { const trigger = document.querySelector('#reminderTypeSelect .radix-select-trigger'); const type = trigger?.getAttribute('data-value') || 'email'; showToast(`${type === 'email' ? '📧 Email' : '📱 SMS'} reminder sent to ${pendingReminderInvoice.patient}`); closeReminderModal(); } }

function openVoidModal(invoice) { pendingVoidInvoice = invoice; document.getElementById('voidModalTitle').textContent = `Are you sure you want to Void Invoice ${invoice.id}?`; document.getElementById('voidModal').style.display = 'grid'; document.getElementById('voidModalBackdrop').classList.add('show'); document.body.style.overflow = 'hidden'; }
function closeVoidModal() { document.getElementById('voidModal').style.display = 'none'; document.getElementById('voidModalBackdrop').classList.remove('show'); pendingVoidInvoice = null; document.body.style.overflow = ''; }
function confirmVoid() { if (pendingVoidInvoice) { pendingVoidInvoice.status = "Void"; renderTables(); showToast(`Invoice ${pendingVoidInvoice.id} voided`); closeVoidModal(); } }

function showActionMenu(btn, invoiceId) { closeActionMenu(); const invoice = invoicesData.find(i => i.id === invoiceId); if (!invoice) return; const rect = btn.getBoundingClientRect(); const menu = document.createElement('div'); menu.className = 'action-menu'; let left = rect.left, top = rect.bottom + 6; if (left + 200 > window.innerWidth) left = window.innerWidth - 210; if (top + 250 > window.innerHeight) top = rect.top - 260; menu.style.top = `${top}px`; menu.style.left = `${left}px`; let h = `<div style="padding:0.5rem 0.75rem;font-size:0.75rem;font-weight:600;color:#6b7280;border-bottom:1px solid #e5e7eb;">Actions</div><button data-action="view" class="action-menu-item"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/></svg>View Invoice</button>`; if (invoice.status !== "Paid" && invoice.status !== "Void") { h += `<button data-action="payment" class="action-menu-item"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect width="20" height="14" x="2" y="5" rx="2"/></svg>Record Payment</button><button data-action="reminder" class="action-menu-item"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M8 2v4M16 2v4M3 10h18"/><rect width="18" height="18" x="3" y="4" rx="2"/></svg>Send Reminder</button><div class="action-divider"></div><button data-action="void" class="action-menu-item" style="color:#dc2626;"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="18" y1="6" x2="6" y2="18"/></svg>Void Invoice</button>`; } h += `<div class="action-divider"></div><button data-action="download" class="action-menu-item"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/></svg>Download PDF</button>`; menu.innerHTML = h; document.body.appendChild(menu); activeActionMenu = menu; const closeFn = e => { if (!menu.contains(e.target) && e.target !== btn) { closeActionMenu(); document.removeEventListener('click', closeFn); } }; setTimeout(() => document.addEventListener('click', closeFn), 10); menu.querySelector('[data-action="view"]')?.addEventListener('click', () => { window.location.href = `invoice.html?id=${invoiceId}`; closeActionMenu(); }); menu.querySelector('[data-action="payment"]')?.addEventListener('click', () => { openPaymentModal(invoice); closeActionMenu(); }); menu.querySelector('[data-action="reminder"]')?.addEventListener('click', () => { openReminderModal(invoice); closeActionMenu(); }); menu.querySelector('[data-action="void"]')?.addEventListener('click', () => { openVoidModal(invoice); closeActionMenu(); }); menu.querySelector('[data-action="download"]')?.addEventListener('click', () => { showToast(`Downloading PDF for Invoice ${invoiceId}`); closeActionMenu(); }); }

function getFilteredData() { let filtered = [...invoicesData]; if (currentTab === "unpaid") filtered = filtered.filter(i => i.status === "Unpaid"); else if (currentTab === "paid") filtered = filtered.filter(i => i.status === "Paid"); else if (currentTab === "partial") filtered = filtered.filter(i => i.status === "Partially Paid"); if (filterStatus !== "all") filtered = filtered.filter(i => i.status.toLowerCase() === filterStatus); if (searchQuery) filtered = filtered.filter(i => i.id.toLowerCase().includes(searchQuery) || i.patient.toLowerCase().includes(searchQuery)); if (sortBy === "newest") filtered.sort((a, b) => new Date(b.date) - new Date(a.date)); else if (sortBy === "oldest") filtered.sort((a, b) => new Date(a.date) - new Date(b.date)); else if (sortBy === "amount_high") filtered.sort((a, b) => b.amount - a.amount); else if (sortBy === "amount_low") filtered.sort((a, b) => a.amount - b.amount); return filtered; }

function renderTables() { const data = getFilteredData(); const allData = invoicesData; const sb = s => `<span class="inline-flex px-2 py-0.5 rounded-full text-xs font-semibold ${s==='Unpaid'?'bg-red-100 text-red-700':s==='Paid'?'bg-green-100 text-green-700':s==='Partially Paid'?'bg-amber-100 text-amber-700':'bg-gray-100 text-gray-700'}">${s}</span>`; document.getElementById('allTableBody').innerHTML = data.map(i => `<tr class="border-b hover:bg-gray-50"><td class="p-3 font-medium">${i.id}</td><td class="p-3">${i.patient}</td><td class="p-3">${i.date}</td><td class="p-3 text-right">$${i.amount}</td><td class="p-3 text-right">$${i.balance}</td><td class="p-3">${sb(i.status)}</td><td class="p-3 hidden md:table-cell">${i.insuranceStatus}</td><td class="p-3 text-right"><button data-id="${i.id}" class="action-trigger w-8 h-8 rounded-full hover:bg-gray-200 inline-flex items-center justify-center"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/><circle cx="5" cy="12" r="1"/></svg></button></td></tr>`).join(''); document.getElementById('unpaidTableBody').innerHTML = allData.filter(i => i.status === "Unpaid").map(i => `<tr class="border-b hover:bg-gray-50"><td class="p-3">${i.id}</td><td class="p-3">${i.patient}</td><td class="p-3">${i.date}</td><td class="p-3 text-right">$${i.amount}</td><td class="p-3">${i.dueDate}</td><td class="p-3 hidden md:table-cell">${i.insuranceStatus}</td><td class="p-3 text-right"><div class="flex justify-end gap-2"><button data-action="payment" data-id="${i.id}" class="bg-primary text-white px-3 h-8 rounded-md text-xs hover:bg-primary/90">Record Payment</button><button data-action="reminder" data-id="${i.id}" class="border border-gray-300 bg-white hover:bg-gray-50 px-3 h-8 rounded-md text-xs">Reminder</button></div></td></tr>`).join(''); document.getElementById('paidTableBody').innerHTML = allData.filter(i => i.status === "Paid").map(i => `<tr class="border-b hover:bg-gray-50"><td class="p-3">${i.id}</td><td class="p-3">${i.patient}</td><td class="p-3">${i.date}</td><td class="p-3 text-right">$${i.amount}</td><td class="p-3 hidden md:table-cell">${i.paymentDate||'—'}</td><td class="p-3 hidden md:table-cell">${i.paymentMethod||'—'}</td><td class="p-3 text-right"><a href="invoice.html?id=${i.id}" class="border border-gray-300 bg-white hover:bg-gray-50 px-3 h-8 rounded-md text-xs inline-flex items-center">View</a></td></tr>`).join(''); document.getElementById('partialTableBody').innerHTML = allData.filter(i => i.status === "Partially Paid").map(i => `<tr class="border-b hover:bg-gray-50"><td class="p-3">${i.id}</td><td class="p-3">${i.patient}</td><td class="p-3">${i.date}</td><td class="p-3 text-right">$${i.amount}</td><td class="p-3 text-right">$${i.paidAmount}</td><td class="p-3 text-right font-bold">$${i.balance}</td><td class="p-3 text-right"><div class="flex justify-end gap-2"><button data-action="payment" data-id="${i.id}" class="bg-primary text-white px-3 h-8 rounded-md text-xs hover:bg-primary/90">Record Payment</button><button data-action="reminder" data-id="${i.id}" class="border border-gray-300 bg-white hover:bg-gray-50 px-3 h-8 rounded-md text-xs">Reminder</button></div></td></tr>`).join(''); document.getElementById('allCount').textContent = `Showing ${data.length} invoices.`; document.getElementById('statOutstanding').textContent = `$${allData.reduce((s, i) => s + i.balance, 0).toFixed(2)}`; document.getElementById('statPaidMonth').textContent = `$${allData.filter(i => i.paymentDate && i.paymentDate.startsWith("2024-04")).reduce((s, i) => s + i.paidAmount, 0).toFixed(2)}`; document.getElementById('statOverdue').textContent = allData.filter(i => i.status !== "Paid" && i.dueDate < "2024-04-30").length; document.getElementById('statClaims').textContent = allData.filter(i => i.insuranceStatus !== "Not Submitted").length; document.querySelectorAll('.action-trigger').forEach(b => b.addEventListener('click', e => { e.stopPropagation(); showActionMenu(b, b.dataset.id); })); document.querySelectorAll('[data-action="payment"]').forEach(b => b.addEventListener('click', e => { const inv = invoicesData.find(i => i.id === b.dataset.id); if (inv) openPaymentModal(inv); })); document.querySelectorAll('[data-action="reminder"]').forEach(b => b.addEventListener('click', e => { const inv = invoicesData.find(i => i.id === b.dataset.id); if (inv) openReminderModal(inv); })); }

const tabs = ['all', 'unpaid', 'paid', 'partial'];
function activateTab(tabId) { currentTab = tabId; tabs.forEach(t => { document.getElementById(`tab-${t}`)?.classList.add('hidden'); const b = document.querySelector(`.tab-btn[data-tab="${t}"]`); if (b) { b.setAttribute('data-state', t === tabId ? 'active' : 'inactive'); t === tabId ? b.classList.add('bg-white', 'text-gray-900', 'shadow-sm') : b.classList.remove('bg-white', 'text-gray-900', 'shadow-sm'); } }); document.getElementById(`tab-${tabId}`)?.classList.remove('hidden'); renderTables(); }
document.querySelectorAll('.tab-btn').forEach(b => b.addEventListener('click', () => activateTab(b.dataset.tab)));

document.getElementById('searchInput')?.addEventListener('input', e => { searchQuery = e.target.value.toLowerCase(); renderTables(); });
document.getElementById('filterBtn')?.addEventListener('click', e => { e.stopPropagation(); document.getElementById('filterDropdown').classList.toggle('hidden'); });
document.querySelectorAll('[data-filter]').forEach(i => i.addEventListener('click', () => { filterStatus = i.dataset.filter; document.getElementById('filterDropdown').classList.add('hidden'); renderTables(); }));
document.getElementById('sortBtn')?.addEventListener('click', e => { e.stopPropagation(); document.getElementById('sortDropdown').classList.toggle('hidden'); });
document.querySelectorAll('[data-sort]').forEach(i => i.addEventListener('click', () => { sortBy = i.dataset.sort; document.getElementById('sortDropdown').classList.add('hidden'); renderTables(); }));
document.getElementById('exportBtn')?.addEventListener('click', () => { const d = getFilteredData(); const csv = [["ID","Patient","Date","Amount","Balance","Status"], ...d.map(i => [i.id, i.patient, i.date, i.amount, i.balance, i.status])].map(r => r.join(",")).join("\n"); const b = new Blob([csv], { type: "text/csv" }); const a = document.createElement('a'); a.href = URL.createObjectURL(b); a.download = `invoices_${new Date().toISOString().slice(0, 10)}.csv`; a.click(); showToast("Export complete"); });
document.addEventListener('click', e => { if (!document.getElementById('filterBtn')?.contains(e.target)) document.getElementById('filterDropdown')?.classList.add('hidden'); if (!document.getElementById('sortBtn')?.contains(e.target)) document.getElementById('sortDropdown')?.classList.add('hidden'); closeActionMenu(); });

document.getElementById('cancelPaymentBtn')?.addEventListener('click', closePaymentModal);
document.getElementById('processPaymentBtn')?.addEventListener('click', processPayment);
document.getElementById('closePaymentModalBtn')?.addEventListener('click', closePaymentModal);
document.getElementById('paymentModalBackdrop')?.addEventListener('click', closePaymentModal);
document.getElementById('cancelReminderBtn')?.addEventListener('click', closeReminderModal);
document.getElementById('sendReminderBtn')?.addEventListener('click', sendReminder);
document.getElementById('closeReminderModalBtn')?.addEventListener('click', closeReminderModal);
document.getElementById('reminderModalBackdrop')?.addEventListener('click', closeReminderModal);
document.getElementById('cancelVoidBtn')?.addEventListener('click', closeVoidModal);
document.getElementById('confirmVoidBtn')?.addEventListener('click', confirmVoid);
document.getElementById('voidModalBackdrop')?.addEventListener('click', closeVoidModal);
document.addEventListener('keydown', e => { if (e.key === 'Escape') { closeVoidModal(); closeReminderModal(); closePaymentModal(); closeActionMenu(); } });

activateTab('all');
</script>
